const AF_LOADED_PACKS = new Set();
function AF_ADD_PACK(province, records) {
  const ids = new Set(BENEFITS.map(b => b.id));
  for (const b of records) if (!ids.has(b.id)) { BENEFITS.push(b); ids.add(b.id); }
  const order = new Map(BENEFIT_INDEX.map((row, i) => [row[0], i]));
  BENEFITS.sort((a, b) => order.get(a.id) - order.get(b.id));
  AF_LOADED_PACKS.add(province);
}

